const ATTACK_DPS_WEAPON_CATEGORIES = {
  1:"素手・ナックル（パンチャー ナックルなど）",
  2:"棍棒・メイス（カッパー メイスなど）",
  3:"棍棒・ハンマー（ウォー ハンマーなど）",
  4:"棍棒・杖（ポール、スタッフなど）",
  5:"刀剣・小太刀／木刀／包丁（ショート ソードなど）",
  6:"刀剣・ナイフ（カッパー ナイフなど）",
  7:"槍・ダガー（カッパー ダガーなど）",
  8:"刀剣・大剣（クレイモアなど）",
  9:"刀剣・斧（グレート アックスなど）",
  10:"刀剣・大鎌（サイスなど）",
  12:"弓（ショート ボウ、ロング ボウなど）",
  13:"両手銃（ドワーヴン ショットガンなど）",
  15:"つるはし（ドワーフのつるはしなど）",
  18:"槍・スピア（カッパー スピアなど）",
  19:"片手銃（ガンファイター ハンドガンなど）"
};
const ATTACK_DPS_REMOTE_MOTIONS = Object.freeze({tackleGun:{label:"片手銃：タックル"},nekomataGun:{label:"両手銃：猫又"},nekomataBow:{label:"弓：猫又"}});
function attackDpsResolvedProfile(cfg) {
  if (cfg.motionProfile === 'tackleGun') return Object.values(ATTACK_DPS_MOTION_PROFILES).find(p=>p.label.split(' / ').includes('ショルダー タックル'));
  if (cfg.motionProfile === 'nekomataGun' || cfg.motionProfile === 'nekomataBow') return ATTACK_DPS_MOTION_PROFILES.form477;
  return ATTACK_DPS_MOTION_PROFILES[cfg.motionProfile === 'auto' ? 'form8' : cfg.motionProfile];
}
function attackDpsCategory(cfg,weapon) {
  if (cfg.weaponCategory !== 'auto') return +cfg.weaponCategory;
  const key=attackDpsWeaponMotionKey(weapon);
  const resolved=key || (cfg.weaponDelaySource==='manual'?cfg.motionProfile:'');
  return resolved==='nekomataBow'?12:resolved==='nekomataGun'?13:resolved==='tackleGun'?19:0;
}
function attackDpsWeaponMotionKey(weapon) {
  const names = (weapon?.weaponReq || []).map(row => row.name || "").join(" ");
  if (names.includes("銃器")) return weapon.weaponTwoHanded === "○" ? "nekomataGun" : "tackleGun";
  if (names.includes("弓")) return "nekomataBow";
  return "";
}
function defaultAttackDpsState() {
  return {
    motionProfile: "auto",
    weaponCategory: "auto",
    damageSource: "current",
    manualDamage: 100,
    weaponDelaySource: "currentWeapon",
    manualWeaponDelay: 300,
    equipmentBuffDelaySource: "auto",
    equipmentBuffDelay: 0,
    attackDelayBuff: 0,
    stDelayBonus: -10,
    manualAttackBonus: true,
    criticalCancel: true,
    damageFrame: 45,
    nonCancelMotionFrames: 90,
    fps: 60,
    simSeconds: 30,
    hitRateSource: "current",
    hitRatePct: 100
  };
}

function normalizeAttackDpsState(raw) {
  const d = defaultAttackDpsState();
  const src = raw && typeof raw === "object" ? raw : {};
  const out = {...d, ...src};
  out.motionProfile = (Object.prototype.hasOwnProperty.call(ATTACK_DPS_REMOTE_MOTIONS, out.motionProfile) || Object.prototype.hasOwnProperty.call(ATTACK_DPS_MOTION_PROFILES, out.motionProfile)) ? out.motionProfile : "auto";
  out.weaponCategory = Object.prototype.hasOwnProperty.call(ATTACK_DPS_WEAPON_CATEGORIES, out.weaponCategory) ? String(out.weaponCategory) : "auto";
  out.damageSource = out.damageSource === "manual" ? "manual" : "current";
  // Existing saved percentages remain explicit manual settings.
  out.hitRateSource = src.hitRateSource === "manual" || (!src.hitRateSource && Object.prototype.hasOwnProperty.call(src,"hitRatePct")) ? "manual" : "current";
  out.weaponDelaySource = out.weaponDelaySource === "manual" ? "manual" : "currentWeapon";
  out.equipmentBuffDelaySource = out.equipmentBuffDelaySource === "manual" ? "manual" : "auto";
  ["manualDamage", "manualWeaponDelay", "equipmentBuffDelay", "attackDelayBuff", "stDelayBonus", "damageFrame", "nonCancelMotionFrames", "fps", "simSeconds", "hitRatePct"].forEach(k => {
    out[k] = parseFloat(out[k]);
    if (!Number.isFinite(out[k])) out[k] = d[k];
  });
  out.fps = Math.max(1, out.fps || d.fps);
  out.simSeconds = Math.max(1, out.simSeconds || d.simSeconds);
  out.hitRatePct = Math.max(0, Math.min(100, out.hitRatePct));
  out.manualAttackBonus = out.manualAttackBonus !== false;
  out.criticalCancel = out.criticalCancel !== false;
  return out;
}

function attackDpsAddDelaySource(bucket, kind, name, value, note="") {
  const n = parseFloat(value);
  if (!Number.isFinite(n) || n === 0) return;
  const item = {kind, name: name || kind, value: n, note};
  bucket.sources.push(item);
  if (kind === "装備") bucket.equipmentTotal += n;
  else bucket.buffTotal += n;
  bucket.total += n;
}

function attackDpsAddDelayPctSource(bucket, kind, name, value, note="") {
  const n = parseFloat(value);
  if (!Number.isFinite(n) || n === 0) return;
  bucket.pctSources.push({kind, name: name || kind, value: n, note});
}

function collectAttackDpsDelaySources(st=state) {
  const baseState = st || state || {};
  const normalizedEquipment = normalizeEquipmentRows(baseState.equipment);
  let buffState = clone(baseState);
  if (typeof expandSkillSimMasteryBuffState === "function") buffState = expandSkillSimMasteryBuffState(buffState);
  if (typeof expandEquipmentBuffState === "function") buffState = expandEquipmentBuffState(buffState);
  if (typeof applyBuffGroupRules === "function") buffState = applyBuffGroupRules(buffState);
  return collectAttackDpsDelaySourcesPrepared(normalizedEquipment, buffState);
}

// Both entry points use the same official delay-source collection. The prepared
// path only skips normalization/Buff resolution already done by computeMetrics.
function collectAttackDpsDelaySourcesPrepared(normalizedEquipment, resolvedBuffState) {
  const bucket = {equipmentTotal:0, buffTotal:0, total:0, sources:[], pctSources:[]};
  bucket.masteryDelaySources = attackDelayBSourcesFromResolvedState({composite:(resolvedBuffState.composite || [])
    .filter(row => row.catalogSource === "skillSimMastery")});
  normalizedEquipment
    .filter(r => r.enabled !== false)
    .forEach(r => {
      const label = `${(r.slot || "装備").replace(/^武器: |^防具: |^装飾: /, "")} ${r.name || "名称未入力"}`.trim();
      attackDpsAddDelaySource(bucket, "装備", label, r.extraAttackDelay, "装備本体");
      attackDpsAddDelayPctSource(bucket, "装備", label, r.extraAttackDelayPct, "攻撃ディレイ%はDPS枠には未反映");
    });

  normalizeCompositeRows(resolvedBuffState.composite)
    .filter(r => r.enabled && !r.excluded && compositeHasEffect(r))
    .forEach(r => {
      const isEquipBuff = /^装備由来[:：]/.test(r.note || "") || /装備Buff$/.test(r.name || "");
      const kind = isEquipBuff ? "装備Buff" : "Buff";
      attackDpsAddDelaySource(bucket, kind, r.name || kind, r.extraAttackDelay, r.note || "");
      attackDpsAddDelayPctSource(bucket, kind, r.name || kind, r.extraAttackDelayPct, "攻撃ディレイ%はDPS枠には未反映");
    });

  bucket.sources.sort((a,b) => a.kind.localeCompare(b.kind, "ja") || a.name.localeCompare(b.name, "ja"));
  bucket.pctSources.sort((a,b) => a.kind.localeCompare(b.kind, "ja") || a.name.localeCompare(b.name, "ja"));
  return bucket;
}

function attackDpsClampPercentForMultiplier(v, min=-99.9, max=999) {
  const n = parseFloat(v) || 0;
  return Math.max(min, Math.min(max, n));
}

function calculateAttackDps({
  cfg,
  weapon=null,
  currentDamage=0,
  currentFollowups=null,
  currentHitRatePct=100,
  currentWeaponDelay=0,
  delayAuto={equipmentTotal:0, buffTotal:0, total:0, sources:[], pctSources:[]}
}={}) {
  cfg = normalizeAttackDpsState(cfg);
  const category = attackDpsCategory(cfg,weapon);
  const warnings = [];

  const damage = cfg.damageSource === "current" ? currentDamage : Math.max(0, +cfg.manualDamage || 0);
  if (cfg.damageSource === "current" && !(damage > 0)) warnings.push("計算タブの予想ダメージが0です。手入力ダメージに切り替えるか、計算条件を確認してください。");

  const weaponDelay = cfg.weaponDelaySource === "currentWeapon" ? currentWeaponDelay : Math.max(0, +cfg.manualWeaponDelay || 0);
  if (category !== 1 && cfg.weaponDelaySource === "currentWeapon" && !(weaponDelay > 0)) warnings.push("現在の計算武器に攻撃間隔がありません。装備詳細に攻撃間隔を入れるか、手入力に切り替えてください。");

  const equipBuffRaw = cfg.equipmentBuffDelaySource === "auto"
    ? delayAuto.total
    : (+cfg.equipmentBuffDelay || 0);
  const equipBuffCapped = Math.max(-60, equipBuffRaw);
  if (equipBuffRaw < -60) warnings.push("装備+攻撃ディレイBuff枠は -60 に丸めています。");
  if (cfg.equipmentBuffDelaySource === "auto" && delayAuto.pctSources.length) warnings.push("攻撃ディレイ% は現状DPS自動枠に未反映です。MoEの短縮値は通常『攻撃ディレイ -X』として登録してください。");

  const masteryDelay = (delayAuto.masteryDelaySources || []).filter(row =>
    weapon && optimizerWeaponSkillNames(weapon).includes(row.skill))
    .reduce((best,row) => !best || row.percent > best.percent ? row : best, null);
  // An explicit B value describes the final same-group choice. Zero uses the
  // active mastery of this weapon; never multiply two B sources together.
  const attackDelayBuff = attackDpsClampPercentForMultiplier(cfg.attackDelayBuff || -(masteryDelay?.percent || 0));
  if (!cfg.attackDelayBuff && masteryDelay) warnings.push(`${masteryDelay.name}の${masteryDelay.skill}スキル短縮 ${masteryDelay.percent}%を自動適用しています。`);
  const stBonus = attackDpsClampPercentForMultiplier(cfg.stDelayBonus);
  const manualBonus = cfg.manualAttackBonus ? -10 : 0;

  const delayMultiplier =
    (100 + equipBuffCapped) / 100 *
    (100 + attackDelayBuff) / 100 *
    (100 + stBonus) / 100 *
    (100 + manualBonus) / 100;

  // Basic unarmed header BC=182 is added before the equipped-weapon floor.
  // With no weapon the same header supplies 182 directly.
  const unarmedBaseDelay = category === 1 ? 182 : 0;
  const baseReuseDelay = Math.max(150,weaponDelay + unarmedBaseDelay);
  const shortenedDelay = Math.max(0, baseReuseDelay * delayMultiplier);
  // Float stores and integerization follow the saved standard reuse publisher.
  const f=Math.fround;
  const statMultiplier=Math.max((100+equipBuffCapped)*f(.01),f(.4));
  const reuseBase=f(baseReuseDelay);
  const reuseScaled=f(reuseBase*statMultiplier);
  const reuseSkill=f(reuseScaled*f((100+attackDelayBuff)/100));
  const reuseInput=f(reuseSkill*f((100+manualBonus)/100));
  const reuseUpdates=Math.trunc(f(reuseInput*f((100+stBonus)/100)));
  const delaySec = reuseUpdates * .016;
  const motion = attackDpsResolvedProfile(cfg);
  const timing = motion?.timings[category];
  const legacyKey=attackDpsWeaponMotionKey(weapon);
  const legacyMismatch=Object.prototype.hasOwnProperty.call(ATTACK_DPS_REMOTE_MOTIONS,cfg.motionProfile) && cfg.weaponDelaySource!=='manual' && legacyKey!==cfg.motionProfile;
  const reuseSupported=Object.prototype.hasOwnProperty.call(ATTACK_DPS_WEAPON_CATEGORIES,category);
  const supported = !!timing && reuseSupported && !legacyMismatch && cfg.manualAttackBonus && (weaponDelay>0 || category===1);

  if (!timing) warnings.push("武器のモーション種別を指定してください。未確認の組み合わせには別の武器の周期を流用しません。");
  if (legacyMismatch) warnings.push("保存されたモーションと現在の武器種が一致しません。モーションを選び直してください。");
  if (!cfg.manualAttackBonus) warnings.push("自動入力の補正は未対応です。手動アタックの条件で計算してください。");
  warnings.push("標準の16ms更新を前提とする理論値です。無限刃・特殊キャンセル・追加の速度効果・通信遅延は含みません。");
  if (motion?.label.includes('免許皆伝')) warnings.push("免許皆伝は過去の実測との不一致が残っています。内部設定からの理論値です。");
  const fps = cfg.fps;
  const damageFrame = null;
  const damageFrameSec = null;
  const motionLockSec = timing ? timing[cfg.criticalCancel?1:0] * .016 : NaN;
  const periodSec = supported ? Math.max(delaySec, motionLockSec) : NaN;

  const simSeconds = Math.max(1, +cfg.simSeconds || 30);
  const hitRate = Math.max(0, Math.min(1, (+(cfg.hitRateSource === "current" ? currentHitRatePct : cfg.hitRatePct) || 0) / 100));
  // 初撃の発生時刻は未測定。時間窓の値は定常周期による期待値。
  const hitCount = periodSec > 0 ? simSeconds / periodSec : NaN;
  const followupRows=cfg.damageSource==='current'?(currentFollowups?.rows||[]):[];
  const includedFollowups=followupRows.filter(r=>r.dpsSupported&&r.status==='supported'&&(r.probability===0||r.durationSeconds<=periodSec));
  const followupExpected=includedFollowups.reduce((s,r)=>s+(r.expected||0),0);
  const followupExpectedActivations=includedFollowups.map(r=>({name:r.name,activations:hitCount*hitRate*r.probability,packets:hitCount*hitRate*r.probability*r.count}));
  const followupComplete=followupRows.every(r=>r.status==='out-of-scope'||includedFollowups.includes(r));
  for(const row of followupRows)if(row.status!=='out-of-scope'&&!includedFollowups.includes(row))
    warnings.push(`${row.name}: ${row.dpsReason||(row.durationSeconds>periodSec?'継続中の再発動による上書きが未確認':row.note)}。追撃をDPSへ未反映。`);
  if(includedFollowups.length)warnings.push('追撃は命中1回につき1回判定し、全回成立する前提です。初撃・末尾の継続時間を含めた定常周期換算です。');
  const expectedDamagePerHit=damage+followupExpected;
  const expectedTotalDamage = expectedDamagePerHit * hitRate * hitCount;

  return {
    cfg, weapon, motion, supported, damage, currentDamage, weaponDelay, currentWeaponDelay,
    equipBuffRaw, equipBuffCapped, delayAuto, attackDelayBuff, stBonus, manualBonus,
    delayMultiplier, unarmedBaseDelay, baseReuseDelay, shortenedDelay, delaySec, fps, damageFrame, damageFrameSec,
    motionLockSec, periodSec, simSeconds, hitRate, hitCount, expectedTotalDamage,
    followupExpected,followupExpectedActivations,followupComplete,expectedDamagePerHit,
    continuousDps: periodSec > 0 ? expectedDamagePerHit * hitRate / periodSec : NaN,
    windowDps: simSeconds > 0 ? expectedTotalDamage / simSeconds : NaN,
    attacksPerMinute: periodSec > 0 ? 60 / periodSec : NaN,
    warnings
  };
}
